import { Component } from '@angular/core';
import { CommonModule } from '@angular/common';

@Component({
  selector: 'app-invitation',
  standalone: true,
  imports: [CommonModule],
  template: `
    <section class="invitation">
      <div class="container">
        <div class="invitation-content">
          <div class="invitation-card">
            <h2>Bądźcie z nami!</h2>
            <p class="subtitle">Serdecznie zapraszamy</p>
            <div class="details">
              <p>Data: 07 Sierpnia 2026</p>
              <p>Godzina: 17:00</p>
              <p>Miejsce: [Nazwa miejsca]</p>
            </div>
          </div>
          <div class="couple-photo">
            <img src="/assets/images/couple-round.jpg" alt="Para młoda">
          </div>
        </div>
      </div>
    </section>
  `,
  styles: [`
    .invitation {
      padding: 5rem 0;
      background: white;
    }

    .container {
      max-width: 1200px;
      margin: 0 auto;
      padding: 0 2rem;
    }

    .invitation-content {
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 3rem;
    }

    .invitation-card {
      flex: 1;
      text-align: center;
      padding: 2rem;
      background: #f8f6f4;
      border-radius: 8px;
      border: 2px solid #c9a961;
    }

    h2 {
      font-family: 'Playfair Display', serif;
      font-size: 2.5rem;
      margin-bottom: 1rem;
      color: #c9a961;
    }

    .subtitle {
      font-family: 'Lato', sans-serif;
      font-size: 1.2rem;
      margin-bottom: 2rem;
      color: #666;
    }

    .details p {
      font-family: 'Lato', sans-serif;
      margin: 0.5rem 0;
      color: #333;
    }

    .couple-photo {
      flex: 1;
      max-width: 400px;
    }

    .couple-photo img {
      width: 100%;
      border-radius: 50%;
      box-shadow: 0 4px 15px rgba(0,0,0,0.2);
    }

    @media (max-width: 768px) {
      .invitation-content {
        flex-direction: column;
      }
    }
  `]
})
export class InvitationComponent {}
